CREATE TABLE IF NOT EXISTS control(id INTEGER PRIMARY KEY CHECK(id=1), ticket INTEGER NOT NULL, retry_at INTEGER NOT NULL, failures INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO control VALUES(1,0,0,0);
CREATE TABLE IF NOT EXISTS lanes(name TEXT PRIMARY KEY,repo TEXT NOT NULL,agent TEXT NOT NULL,labels TEXT NOT NULL,generation INTEGER NOT NULL,paused INTEGER NOT NULL DEFAULT 0,discovery_after TEXT,next_scan INTEGER NOT NULL,ticket INTEGER NOT NULL,last_scan_at INTEGER,last_error TEXT,gaps INTEGER NOT NULL DEFAULT 0,next_batch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS prs(lane TEXT NOT NULL REFERENCES lanes(name),number INTEGER NOT NULL,head TEXT NOT NULL,state TEXT NOT NULL,draft INTEGER NOT NULL,in_scope INTEGER NOT NULL,tracking INTEGER NOT NULL DEFAULT 1,initializing INTEGER NOT NULL,timeline_cursor TEXT,threads_after TEXT,due INTEGER NOT NULL,ticket INTEGER NOT NULL,last_success INTEGER,last_error TEXT,resync INTEGER NOT NULL DEFAULT 0,gaps INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(lane,number));
CREATE TABLE IF NOT EXISTS threads(lane TEXT NOT NULL,number INTEGER NOT NULL,id TEXT NOT NULL,signature TEXT NOT NULL,PRIMARY KEY(lane,number,id),FOREIGN KEY(lane,number) REFERENCES prs(lane,number));
CREATE TABLE IF NOT EXISTS pending(lane TEXT NOT NULL,number INTEGER NOT NULL,generation INTEGER NOT NULL,head TEXT NOT NULL,state TEXT NOT NULL,reasons TEXT NOT NULL,PRIMARY KEY(lane,number,generation),FOREIGN KEY(lane,number) REFERENCES prs(lane,number));
CREATE TABLE IF NOT EXISTS outbox(lane TEXT NOT NULL REFERENCES lanes(name),sequence INTEGER NOT NULL,id TEXT NOT NULL UNIQUE,recipient TEXT NOT NULL,body TEXT NOT NULL,generation INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',last_error TEXT,PRIMARY KEY(lane,sequence));
PRAGMA user_version=1;
